'use client';

import { useEffect } from 'react';

import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { ListChecksIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { ApprovalTile } from './approval-tile';
import { ContextTile } from './context-tile';
import { CostTile } from './cost-tile';
import { APPROVAL, SECTION } from './data';
import { PlanTile } from './plan-tile';
import { PromptTile } from './prompt-tile';
import {
  doneCountOf,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  TRAY_READ_MS,
  type RunState,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function spokenLineOf(state: RunState) {
  if (state.approval === 'waiting') {
    return `Ledgerfinch asks: ${APPROVAL.title}. Approve or decline.`;
  }
  if (state.approval === 'approved') {
    return 'Approved, the matches are posted';
  }
  if (state.approval === 'declined') {
    return 'Declined, the step was skipped';
  }
  return '';
}

export default function Features04() {
  const { ref, isAutoplaying, state, act, pressed, isFinished, restart } =
    useSession(SESSION);
  const isReading = state.tray === 'reading';
  const isSentByPerson = isReading && !isAutoplaying;
  const doneCount = doneCountOf(state);
  const message = spokenUnless(isAutoplaying, spokenLineOf(state));
  const canReplay = isFinished && !isAutoplaying;

  useKeptHeight(ref);

  useEffect(() => {
    if (!isSentByPerson) {
      return;
    }
    const timer = setTimeout(() => act({ type: 'planned' }), TRAY_READ_MS);
    return () => clearTimeout(timer);
  }, [isSentByPerson, act]);

  return (
    <div ref={ref} className='@container min-h-[60rem]'>
      <section className='px-4 py-16 @2xl:px-6 @2xl:py-24 @5xl:px-8'>
        <div className='mx-auto flex max-w-6xl flex-col gap-10'>
          <header className='flex flex-wrap items-end justify-between gap-x-6 gap-y-4'>
            <div className='flex max-w-2xl flex-col gap-3'>
              <p className='text-primary-ink flex items-center gap-1.5 text-[13px] font-medium'>
                <ListChecksIcon className='size-4' />
                {SECTION.label}
              </p>
              <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
                {SECTION.title}
              </h2>
              <p className='text-muted-foreground text-base text-pretty'>
                {SECTION.lead}
              </p>
            </div>
            <div className='flex flex-wrap items-center gap-2'>
              <ReplayButton
                isShown={canReplay}
                onReplay={restart}
                label='Replay'
              />
              <Badge variant='secondary'>{SECTION.figures}</Badge>
            </div>
          </header>
          <ul className='grid gap-3 @4xl:grid-cols-6'>
            <li className='flex @4xl:col-span-3'>
              <PromptTile
                prompt={state.prompt}
                tray={state.tray}
                isSendPressed={pressed === 'send'}
                onType={(value) => act({ type: 'typed', value })}
                onSend={() => act({ type: 'sent' })}
              />
            </li>
            <li className='flex @4xl:col-span-3'>
              <PlanTile steps={state.steps} doneCount={doneCount} />
            </li>
            <li className='flex @4xl:col-span-2'>
              <ApprovalTile
                approval={state.approval}
                isApprovePressed={pressed === 'approve'}
                onApprove={() => act({ type: 'approved' })}
                onDecline={() => act({ type: 'declined' })}
              />
            </li>
            <li className='flex @4xl:col-span-2'>
              <ContextTile percent={state.context} />
            </li>
            <li className='flex @4xl:col-span-2'>
              <CostTile cost={state.cost} />
            </li>
          </ul>
        </div>
      </section>
      <LiveRegion message={message} />
    </div>
  );
}

'use client';

import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { CircleDashedIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';
import { Wash } from '@/registry/ndeko/ui/wash';

import { APPROVAL, TILES } from './data';
import type { Approval } from './session';
import { Tile } from './tile';

function layerClassOf(isActive: boolean) {
  if (isActive) {
    return 'opacity-100 transition-opacity delay-100 duration-200 ease-(--ease-out-strong)';
  }
  return 'pointer-events-none opacity-0 transition-opacity duration-150';
}

type ApprovalTileProps = {
  approval: Approval;
  isApprovePressed: boolean;
  onApprove: () => void;
  onDecline: () => void;
};

export function ApprovalTile({
  approval,
  isApprovePressed,
  onApprove,
  onDecline,
}: ApprovalTileProps) {
  const isNone = approval === 'none';
  const isWaiting = approval === 'waiting';
  const isApproved = approval === 'approved';
  const isDeclined = approval === 'declined';

  return (
    <Tile copy={TILES.approval}>
      <Wash color='var(--warning)' isShown={isWaiting} />
      <div className='grid *:col-start-1 *:row-start-1'>
        <p
          inert={!isNone}
          aria-hidden={!isNone}
          className={cn(
            'text-muted-foreground flex items-center gap-2 text-[13px]',
            layerClassOf(isNone)
          )}
        >
          <CircleDashedIcon className='size-4 shrink-0' />
          Nothing is waiting for you
        </p>
        <div
          inert={!isWaiting}
          aria-hidden={!isWaiting}
          className={cn(
            'bg-card dark:bg-foreground/[0.06] flex flex-col gap-3 rounded-xl p-3 shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
            layerClassOf(isWaiting)
          )}
        >
          <div className='flex flex-col gap-1'>
            <p className='text-[13px] font-medium'>{APPROVAL.title}</p>
            <p className='text-muted-foreground text-xs text-pretty'>
              {APPROVAL.detail}
            </p>
          </div>
          <div className='flex flex-wrap gap-2'>
            <Button
              size='sm'
              onClick={onApprove}
              className={pressedSolidOf(isApprovePressed)}
            >
              Approve
            </Button>
            <Button size='sm' variant='outline' onClick={onDecline}>
              Decline
            </Button>
          </div>
        </div>
        <p
          inert={!isApproved}
          aria-hidden={!isApproved}
          className={cn(
            'flex items-center gap-2 text-[13px]',
            layerClassOf(isApproved)
          )}
        >
          {isApproved && <DrawnCheck tone='success' entrance='draw' />}
          Approved, 38 matches posted
        </p>
        <p
          inert={!isDeclined}
          aria-hidden={!isDeclined}
          className={cn(
            'text-muted-foreground flex items-center gap-2 text-[13px]',
            layerClassOf(isDeclined)
          )}
        >
          <XIcon className='size-4 shrink-0' />
          Declined, the step was skipped
        </p>
      </div>
    </Tile>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { formatTokens } from '@/registry/ndeko/lib/agent-run';

import { CONTEXT_LIMIT_TOKENS, TILES } from './data';
import { Tile } from './tile';

const RING_LENGTH = 100;

type ContextTileProps = {
  percent: number;
};

export function ContextTile({ percent }: ContextTileProps) {
  const offset = RING_LENGTH - percent;
  const usedTokens = (percent / 100) * CONTEXT_LIMIT_TOKENS;
  const used = formatTokens(usedTokens);
  const limit = formatTokens(CONTEXT_LIMIT_TOKENS);

  return (
    <Tile copy={TILES.context} stageClassName='items-center gap-3'>
      <div
        role='img'
        aria-label={`Context window ${Math.round(percent)} percent full`}
        className='relative size-28'
      >
        <svg viewBox='0 0 100 100' aria-hidden='true' className='size-full'>
          <circle
            cx='50'
            cy='50'
            r='44'
            fill='none'
            strokeWidth='8'
            className='stroke-foreground/10'
          />
          <circle
            cx='50'
            cy='50'
            r='44'
            fill='none'
            strokeWidth='8'
            strokeLinecap='round'
            pathLength={RING_LENGTH}
            strokeDasharray={RING_LENGTH}
            strokeDashoffset={offset}
            transform='rotate(-90 50 50)'
            className='stroke-primary transition-[stroke-dashoffset] duration-700 ease-(--ease-out-strong) motion-reduce:transition-none'
          />
        </svg>
        <span
          aria-hidden='true'
          className='absolute inset-0 flex items-center justify-center text-2xl font-semibold'
        >
          <MotionNumber value={Math.round(percent)} suffix='%' />
        </span>
      </div>
      <p className='text-muted-foreground text-xs tabular-nums'>
        {used} of {limit} tokens
      </p>
    </Tile>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';

import { BUDGET_USD, TILES } from './data';
import { Tile } from './tile';

const MONEY = { minimumFractionDigits: 3, maximumFractionDigits: 3 };

type CostTileProps = {
  cost: number;
};

export function CostTile({ cost }: CostTileProps) {
  const share = Math.min(cost / BUDGET_USD, 1);
  const barStyle = { transform: `scaleX(${share})` };
  const budget = BUDGET_USD.toFixed(2);

  return (
    <Tile copy={TILES.cost} stageClassName='gap-4'>
      <div className='flex flex-col gap-1'>
        <span className='text-muted-foreground text-xs'>Spent this run</span>
        <MotionNumber
          value={cost}
          prefix='$'
          format={MONEY}
          className='text-4xl font-semibold'
        />
      </div>
      <div className='flex flex-col gap-1.5'>
        <div
          role='progressbar'
          aria-label='Share of the budget spent'
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round(share * 100)}
          className='bg-foreground/10 h-1.5 overflow-hidden rounded-full'
        >
          <div
            style={barStyle}
            className='bg-primary h-full w-full origin-left rounded-full transition-transform duration-500 ease-(--ease-out-strong) motion-reduce:transition-none'
          />
        </div>
        <span className='text-muted-foreground text-xs tabular-nums'>
          Budget ${budget}
        </span>
      </div>
    </Tile>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import {
  HourglassIcon,
  LoaderIcon,
  MinusIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';

import { PLAN_STEPS, TILES } from './data';
import type { PlanStatus } from './session';
import { Tile } from './tile';

const STATUS_WORD: Record<PlanStatus, string> = {
  upcoming: 'Upcoming',
  running: 'Running',
  waiting: 'Waiting for you',
  done: 'Done',
  skipped: 'Skipped',
};

function StepGlyph({ status }: { status: PlanStatus }) {
  if (status === 'done') {
    return <DrawnCheck tone='success' entrance='draw' />;
  }
  if (status === 'running') {
    return <LoaderIcon className='text-muted-foreground size-4 animate-spin' />;
  }
  if (status === 'waiting') {
    return <HourglassIcon className='text-warning-foreground size-4' />;
  }
  if (status === 'skipped') {
    return <MinusIcon className='text-muted-foreground size-4' />;
  }
  return (
    <span className='hairline-ring ring-foreground/25 size-3.5 rounded-full' />
  );
}

function liftedOf(status: PlanStatus) {
  const isActive = status === 'running' || status === 'waiting';
  if (isActive) {
    return 'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.06]';
  }
  return undefined;
}

function mutedOf(status: PlanStatus) {
  const isQuiet = status === 'upcoming' || status === 'skipped';
  if (isQuiet) {
    return 'text-muted-foreground';
  }
  return undefined;
}

type PlanTileProps = {
  steps: PlanStatus[];
  doneCount: number;
};

export function PlanTile({ steps, doneCount }: PlanTileProps) {
  return (
    <Tile copy={TILES.plan}>
      <div className='flex flex-col gap-2'>
        <p className='text-muted-foreground flex items-baseline gap-1 px-2 text-xs tabular-nums'>
          <MotionNumber value={doneCount} />
          <span>of {PLAN_STEPS.length} done</span>
        </p>
        <ol aria-label='Plan' className='flex flex-col gap-0.5'>
          {PLAN_STEPS.map((title, index) => {
            const status = steps[index];

            return (
              <li
                key={title}
                className={cn(
                  'flex h-8 items-center gap-2.5 rounded-lg px-2 text-[13px] transition-[background-color,box-shadow] duration-200',
                  liftedOf(status)
                )}
              >
                <span className='flex size-[18px] shrink-0 items-center justify-center'>
                  <Swap swapKey={status}>
                    <StepGlyph status={status} />
                  </Swap>
                </span>
                <span
                  className={cn(
                    'min-w-0 flex-1 truncate transition-colors duration-200',
                    mutedOf(status)
                  )}
                >
                  <span className='sr-only'>{STATUS_WORD[status]}: </span>
                  {title}
                </span>
              </li>
            );
          })}
        </ol>
      </div>
    </Tile>
  );
}

'use client';

import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import {
  ArrowUpIcon,
  CircleDashedIcon,
  LoaderIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';
import { Textarea } from '@/registry/ndeko/ui/textarea';

import { PLAN_STEPS, PROMPT, TILES } from './data';
import type { TrayStatus } from './session';
import { Tile } from './tile';

const TRAY_LINE: Record<TrayStatus, string> = {
  idle: 'Ready for a prompt',
  reading: 'Reading 3 files',
  planned: `Plan ready, ${PLAN_STEPS.length} steps`,
};

function TrayGlyph({ tray }: { tray: TrayStatus }) {
  if (tray === 'planned') {
    return <DrawnCheck tone='success' entrance='draw' />;
  }
  if (tray === 'reading') {
    return <LoaderIcon className='text-info-foreground size-4 animate-spin' />;
  }
  return <CircleDashedIcon className='size-4' />;
}

type PromptTileProps = {
  prompt: string;
  tray: TrayStatus;
  isSendPressed: boolean;
  onType: (value: string) => void;
  onSend: () => void;
};

export function PromptTile({
  prompt,
  tray,
  isSendPressed,
  onType,
  onSend,
}: PromptTileProps) {
  const isEmpty = prompt.trim() === '';
  const line = TRAY_LINE[tray];

  function sendOnEnter(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    const isEnter = event.key === 'Enter';
    const isPlain = !event.shiftKey;
    const hasText = !isEmpty;
    if (isEnter && isPlain && hasText) {
      event.preventDefault();
      onSend();
    }
  }

  return (
    <Tile copy={TILES.prompt}>
      <div className='flex flex-col gap-2'>
        <div className='relative'>
          <Textarea
            rows={3}
            value={prompt}
            placeholder={PROMPT.placeholder}
            aria-label={PROMPT.label}
            onChange={(event) => onType(event.target.value)}
            onKeyDown={sendOnEnter}
            className='min-h-24 pe-12 text-[13px]'
          />
          <Button
            type='button'
            size='icon-sm'
            aria-label='Send the prompt'
            disabled={isEmpty}
            onClick={onSend}
            className={cn(
              'absolute end-2 bottom-2',
              pressedSolidOf(isSendPressed)
            )}
          >
            <ArrowUpIcon />
          </Button>
        </div>
        <p
          aria-label='Status'
          className='text-muted-foreground flex h-6 items-center px-1 text-xs'
        >
          <Swap swapKey={tray}>
            <span className='flex items-center gap-1.5'>
              <TrayGlyph tray={tray} />
              <span>{line}</span>
            </span>
          </Swap>
        </p>
      </div>
    </Tile>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';

import type { TileCopy } from './data';

type TileProps = {
  copy: TileCopy;
  stageClassName?: string;
  children: React.ReactNode;
};

/** The stage radius is the tile radius minus the padding between them, so the curves run parallel. */
export function Tile({ copy, stageClassName, children }: TileProps) {
  return (
    <article className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex min-w-0 flex-1 flex-col gap-4 rounded-2xl p-2 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
      <div
        className={cn(
          'bg-foreground/[0.04] relative isolate flex min-h-52 flex-1 flex-col justify-center rounded-[calc(var(--radius-2xl)-0.5rem)] p-4',
          stageClassName
        )}
      >
        {children}
      </div>
      <div className='flex flex-col gap-1 px-2 pb-2'>
        <h3 className='text-sm font-medium'>{copy.title}</h3>
        <p className='text-muted-foreground text-[13px] text-pretty'>
          {copy.text}
        </p>
      </div>
    </article>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import { PLAN_STEPS, PROMPT_TEXT } from './data';

export type PlanStatus =
  'upcoming' | 'running' | 'waiting' | 'done' | 'skipped';

export type TrayStatus = 'idle' | 'reading' | 'planned';

export type Approval = 'none' | 'waiting' | 'approved' | 'declined';

export type RunState = {
  prompt: string;
  tray: TrayStatus;
  steps: PlanStatus[];
  context: number;
  cost: number;
  approval: Approval;
};

export type RunAction =
  | { type: 'typed'; value: string }
  | { type: 'sent' }
  | { type: 'read' }
  | { type: 'planned' }
  | { type: 'advanced'; step: number; context: number; cost: number }
  | { type: 'asked' }
  | { type: 'approved' }
  | { type: 'declined' };

type Step = SessionStep<RunState, RunAction>;

const LAST_STEP = PLAN_STEPS.length - 1;

const APPROVED_COST_USD = 0.014;

const APPROVED_CONTEXT_PERCENT = 8;

function stepsOf(status: PlanStatus): PlanStatus[] {
  return PLAN_STEPS.map(() => status);
}

export const INITIAL: RunState = {
  prompt: '',
  tray: 'idle',
  steps: stepsOf('upcoming'),
  context: 0,
  cost: 0,
  approval: 'none',
};

function withStep(
  steps: PlanStatus[],
  index: number,
  status: PlanStatus
): PlanStatus[] {
  return steps.map((current, position) => {
    if (position === index) {
      return status;
    }
    return current;
  });
}

function planned(state: RunState): RunState {
  const isNotStarted = state.steps[0] === 'upcoming';
  if (!isNotStarted) {
    return { ...state, tray: 'planned' };
  }
  const steps = withStep(state.steps, 0, 'running');
  return { ...state, tray: 'planned', steps };
}

function advanced(
  state: RunState,
  step: number,
  context: number,
  cost: number
): RunState {
  let steps = withStep(state.steps, step, 'done');
  const next = step + 1;
  const isAutomatic = next < LAST_STEP;
  const isUpcoming = state.steps[next] === 'upcoming';
  if (isAutomatic && isUpcoming) {
    steps = withStep(steps, next, 'running');
  }
  return { ...state, steps, context, cost };
}

function asked(state: RunState): RunState {
  if (state.approval !== 'none') {
    return state;
  }
  const steps = withStep(state.steps, LAST_STEP, 'waiting');
  return { ...state, steps, approval: 'waiting' };
}

function approved(state: RunState): RunState {
  if (state.approval !== 'waiting') {
    return state;
  }
  const steps = withStep(state.steps, LAST_STEP, 'done');
  return {
    ...state,
    steps,
    approval: 'approved',
    cost: state.cost + APPROVED_COST_USD,
    context: state.context + APPROVED_CONTEXT_PERCENT,
  };
}

function declined(state: RunState): RunState {
  if (state.approval !== 'waiting') {
    return state;
  }
  const steps = withStep(state.steps, LAST_STEP, 'skipped');
  return { ...state, steps, approval: 'declined' };
}

export function reducer(state: RunState, action: RunAction): RunState {
  switch (action.type) {
    case 'typed':
      return { ...state, prompt: action.value };
    case 'sent':
      return { ...state, tray: 'reading' };
    case 'read':
      return { ...state, context: 18, cost: 0.012 };
    case 'planned':
      return planned(state);
    case 'advanced':
      return advanced(state, action.step, action.context, action.cost);
    case 'asked':
      return asked(state);
    case 'approved':
      return approved(state);
    case 'declined':
      return declined(state);
  }
}

export function doneCountOf(state: RunState) {
  const done = state.steps.filter((status) => status === 'done');
  return done.length;
}

const KEY_MS = 38;

/** How long the tray reads for a person who sends a prompt themselves. */
export const TRAY_READ_MS = 1400;

function typing(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((value, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'typed', value },
  }));
}

function hasAnswered(state: RunState) {
  return state.approval !== 'waiting';
}

/**
 * The agent works on its own clock: it reads, plans and ticks its steps. The prompt is typed and
 * the approval is answered by the demonstration until a person takes over, and the run waits for
 * them from then on.
 */
export const SCRIPT: Step[] = [
  ...typing(PROMPT_TEXT, 700),
  { after: 600, by: 'demo', press: 'send', action: { type: 'sent' } },
  { after: 1100, action: { type: 'read' } },
  { after: 900, action: { type: 'planned' } },
  {
    after: 1100,
    action: { type: 'advanced', step: 0, context: 34, cost: 0.027 },
  },
  {
    after: 1200,
    action: { type: 'advanced', step: 1, context: 52, cost: 0.041 },
  },
  {
    after: 1200,
    action: { type: 'advanced', step: 2, context: 63, cost: 0.052 },
  },
  { after: 700, action: { type: 'asked' } },
  {
    after: 2600,
    by: 'person',
    press: 'approve',
    action: { type: 'approved' },
    isAnswered: hasAnswered,
  },
];

/** Under reduced motion the run rests where it waits on a person. */
export const RESTING: RunState = {
  prompt: PROMPT_TEXT,
  tray: 'planned',
  steps: ['done', 'done', 'done', 'waiting'],
  context: 63,
  cost: 0.052,
